function findUser(id) {
  return { sql: 'SELECT * FROM users WHERE id = $1', params: [id] };
}
const q = findUser('1; DROP TABLE users;');
console.log(q.params[0] === '1; DROP TABLE users;' ? 'safe query built' : 'unsafe');

